import unreal

ns_crt = unreal.load_asset('/Game/Niagara/NS_CRT_DotGrid')

# List all properties on the system
props = unreal.SystemLibrary.get_class_display_name(type(ns_crt))
print(f"Class: {props}")

# Try to find emitter-related properties
for attr_name in ['emitter_handles', 'emitters', 'emitter_data', 'system_emitters']:
    try:
        val = ns_crt.get_editor_property(attr_name)
        print(f"{attr_name}: {val}")
    except Exception as e:
        pass

# Check what user parameters exist by looking at the component on an actor
eas = unreal.EditorActorSubsystem()
actors = eas.get_all_level_actors()
niagara_actors = [a for a in actors if 'DotGrid' in a.get_actor_label()]
print(f"\nDotGrid actors in level: {[a.get_actor_label() for a in niagara_actors]}")

for a in niagara_actors:
    comps = a.get_components_by_class(unreal.NiagaraComponent)
    for c in comps:
        print(f"\nComponent: {c.get_name()}")
        asset = c.get_asset()
        print(f"  Asset: {asset.get_name() if asset else 'None'}")

        # Try to list override parameters
        try:
            overrides = c.get_editor_property('override_parameters')
            print(f"  Override params: {overrides}")
        except:
            pass

        # Check common user parameter names
        for pname in ['User.GridWidth', 'User.GridHeight', 'User.BoxSize', 'User.Scale', 'User.Extent', 'User.Spacing', 'User.ParticleCount', 'User.GridSize', 'User.Rows', 'User.Columns']:
            try:
                # Try float
                val = c.get_niagara_variable_float(pname)
                if val != 0.0:
                    print(f"  {pname} (float) = {val}")
            except:
                pass
            try:
                val = c.get_niagara_variable_int(pname)
                if val != 0:
                    print(f"  {pname} (int) = {val}")
            except:
                pass
            try:
                val = c.get_niagara_variable_vec3(pname)
                print(f"  {pname} (vec3) = {val}")
            except:
                pass

